DROP TABLE IF EXISTS `global_stats`;
CREATE TABLE `global_stats` (
  `id` int NOT NULL AUTO_INCREMENT,
  `dailyDepots` decimal(15,2) DEFAULT '0.00',
  `dailyRetraits` decimal(15,2) DEFAULT '0.00',
  `cycleDepots` decimal(15,2) DEFAULT '0.00',
  `cycleRetraits` decimal(15,2) DEFAULT '0.00',
  `argentDebut` decimal(15,2) DEFAULT '0.00',
  `reglements` text COLLATE utf8mb4_unicode_ci,
  `admin_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'zubiksservice@gmail.com',
  `admin_password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profilePhoto` longtext COLLATE utf8mb4_unicode_ci,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

