DROP TABLE IF EXISTS `members`;
CREATE TABLE `members` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `postnom` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `sexe` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'M',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'user',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `parts` int DEFAULT '1',
  `totalDepot` decimal(15,2) DEFAULT '0.00',
  `totalRetrait` decimal(15,2) DEFAULT '0.00',
  `dateAjout` datetime DEFAULT CURRENT_TIMESTAMP,
  `profilePhoto` longtext COLLATE utf8mb4_unicode_ci,
  `notifications` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `memberId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `memberNom` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `date` date NOT NULL,
  `timestamp` datetime DEFAULT CURRENT_TIMESTAMP,
  `adminNom` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'Admin',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `archives`;
CREATE TABLE `archives` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` datetime DEFAULT CURRENT_TIMESTAMP,
  `cycleDepots` decimal(15,2) DEFAULT '0.00',
  `cycleRetraits` decimal(15,2) DEFAULT '0.00',
  `solde` decimal(15,2) DEFAULT '0.00',
  `userId` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `daily_archives`;
CREATE TABLE `daily_archives` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` date NOT NULL,
  `dailyDepots` decimal(15,2) DEFAULT '0.00',
  `dailyRetraits` decimal(15,2) DEFAULT '0.00',
  `solde` decimal(15,2) DEFAULT '0.00',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `messages`;
CREATE TABLE `messages` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `memberId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `senderName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `timestamp` datetime DEFAULT CURRENT_TIMESTAMP,
  `readByAdmin` tinyint(1) DEFAULT '0',
  `readByUser` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=1;
